function WeightInput({value, label, disabled, onChange}: {value:number|null; label:string; disabled:boolean; onChange:(v:number|null)=>void}) {
 const [text,setText]=useState(value===null?'':String(value)); const emitted=useRef(value);
 useEffect(()=>{if(value!==emitted.current){emitted.current=value;setText(value===null?'':String(value))}},[value]);
 return <input aria-label={label} inputMode="decimal" placeholder="kg" value={text} disabled={disabled} onChange={e=>{const v=e.target.value;setText(v);const parsed=parseWeight(v);emitted.current=parsed;onChange(parsed)}}/>;
}
function RepsInput({value, label, onChange}: {value:number|null; label:string; onChange:(v:number|null)=>void}) {
 const [text,setText]=useState(value===null?'':String(value)); const emitted=useRef(value);
 useEffect(()=>{if(value!==emitted.current){emitted.current=value;setText(value===null?'':String(value))}},[value]);
 return <input aria-label={label} inputMode="numeric" placeholder="reps" value={text} onChange={e=>{const v=e.target.value;setText(v);const parsed=/^\d{1,4}$/.test(v)?Number(v):null;emitted.current=parsed;onChange(parsed)}}/>;
}
function ColorPicker({ value, onChange }: {value:string; onChange:(v:string)=>void}) {
  return <fieldset className="color-field"><legend>Color</legend><div className="colors">{COLORS.map((c, i) => <button key={c} type="button" aria-label={`Color ${['azul', 'morado', 'verde', 'rojo', 'naranja', 'gris'][i]}`} aria-pressed={value === c} className={`color-choice ${value === c ? 'selected' : ''}`} style={{backgroundColor:c}} onClick={() => onChange(c)}>{value === c ? '✓' : ''}</button>)}</div></fieldset>;
}
function Back({onClick, title, right}: {onClick:()=>void; title:string; right?:React.ReactNode}) { return <header className="page-header"><button className="icon-button back" aria-label="Volver" onClick={onClick}>‹</button><h1>{title}</h1>{right || <span className="header-spacer"/>}</header>; }
function ExerciseMark({name}: {name:string}) { return <span className="exercise-mark" aria-hidden="true"><Dumbbell size={21}/></span>; }
function Modal({title, onClose, children}: {title:string; onClose:()=>void; children:React.ReactNode}) {
 const modalRef=useRef<HTMLElement>(null);
 useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';(modalRef.current?.querySelector<HTMLElement>('input')||modalRef.current?.querySelector<HTMLElement>('button'))?.focus();return()=>{document.body.style.overflow=overflow;previous?.focus()}},[]);
 return <div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}} onKeyDown={e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const items=Array.from(modalRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not([hidden]),select,summary')||[]).filter(el=>el.getClientRects().length>0);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}}><section ref={modalRef} className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><div><span className="eyebrow">CONSTRUYE TU SESIÓN</span><h2>{title}</h2></div><button className="icon-button" aria-label="Cerrar" onClick={onClose}>×</button></div>{children}</section></div>;
}
function periodBounds(kind:'week'|'month', anchor:string, today:string) {
 const d = new Date(`${anchor}T12:00:00Z`);
 if(kind === 'month') { const start = `${anchor.slice(0,7)}-01`; const end = dayKey(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0,12))); return {start,end:anchor.slice(0,7)===today.slice(0,7)?today:end}; }
 const dow=(d.getUTCDay()+6)%7; const start=shift(anchor,-dow); const end=shift(start,6); return {start,end:today>=start&&today<=end?today:end};
}

